/**
 * Synthetic demo dossiers of seven fictional companies (Stage 04, decision D-01).
 *
 * The JSON is generated by `python -m multiverse_contracts.demo` and every record is
 * validated against the Python contracts in CI (test_demo_fixtures.py), which is why
 * the cast below is safe. Import this only on the server: it is about 280 KB.
 */
import type { CompanyDossier } from "./generated/contracts";
import data from "../../fixtures/demo/companies.json";

// JSON imports widen literals to string and arrays lose non-empty tuple types, so TypeScript
// cannot check this file against the contract; the Python validation in CI does.
export const DEMO_DOSSIERS: readonly CompanyDossier[] =
  data as unknown as readonly CompanyDossier[];
